// Hace lo mismo que el WhatsApp Trigger: Meta manda un paquete con "entry" y "changes",
// y el trigger entrega solo la parte "value" de cada cambio (contactos, mensajes, etc.).
const body = $input.first().json.body;
const salida = [];
for (const entry of body.entry ?? []) {
  for (const change of entry.changes ?? []) {
    // Igual que el trigger con "Receive Message Status Updates" vacío:
    // los avisos de entregado/leído no pasan.
    if (change.value?.statuses) continue;
    salida.push({ json: { ...change.value, field: change.field } });
  }
}
return salida;

